            r = pl.multiple_of(c * _CH, _CH)
            x = p_ref[pl.ds(r, _CH), :].astype(jnp.float32)
            y = l_ref[pl.ds(r, _CH), :].astype(jnp.float32)
            return carry + term(x, y).reshape(_CH // 8, 8, w).sum(axis=0)
        return jax.lax.fori_loop(0, tb // _CH, body, jnp.zeros((8, w), jnp.float32), unroll=2)

    def mse(x, y):
        d = (0.5 * jnp.tanh(0.5 * x) + 0.5) - y
        return d * d

    def bce(x, y):
        return jnp.maximum(x, 0.0) - x * y + jnp.log1p(jnp.exp(-jnp.abs(x)))

